<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="robots" content="noindex,nofollow,noarchive"><title>My Hospital Review · I Love My Body</title><style>
:root{--bg:#fbf8f5;--card:#fff;--ink:#2a211f;--muted:#716761;--line:#eadfd9;--rose:#a94f63;--peach:#f2c8b2;--soft:#fff2ed;--good:#e9f6ee;--goodink:#2f6b49;--warn:#fff5df;--warnink:#8b5b12;--unknown:#f2f2f2;--danger:#fff0f0}*{box-sizing:border-box}body{margin:0;background:linear-gradient(180deg,#fffaf7,var(--bg));color:var(--ink);font:15px/1.55 system-ui,-apple-system,Segoe UI,sans-serif}.wrap{max-width:1480px;margin:auto;padding:22px 18px 70px}.top{display:flex;justify-content:space-between;gap:14px;align-items:center}.brand b{display:block;font-size:20px}.brand small{color:var(--muted);letter-spacing:.12em}.back{color:var(--rose);text-decoration:none;font-weight:700}.hero{margin:30px 0 18px;padding:28px;border:1px solid var(--line);border-radius:22px;background:linear-gradient(135deg,#fff,#fff3ed)}.hero h1{margin:6px 0 8px;font:500 clamp(36px,5vw,62px)/1.02 Georgia,serif}.hero p{max-width:900px;color:var(--muted);font-size:17px}.ey{color:var(--rose);font-size:11px;font-weight:800;letter-spacing:.14em}.summary{display:grid;grid-template-columns:repeat(3,1fr);gap:12px}.sum{padding:16px;border-radius:16px;border:1px solid var(--line);background:var(--card)}.sum b{font-size:28px}.sum span{display:block;color:var(--muted)}.section{margin-top:18px;padding:22px;border:1px solid var(--line);border-radius:20px;background:var(--card)}h2{margin:4px 0 6px;font:500 30px Georgia,serif}.lead{color:var(--muted);max-width:980px}.cards{display:grid;grid-template-columns:repeat(3,1fr);gap:12px;margin-top:16px}.result{padding:16px;border:1px solid var(--line);border-radius:14px}.result.good{background:var(--good)}.result.attn{background:var(--warn)}.result.unknown{background:var(--unknown)}.pill{display:inline-block;padding:4px 8px;border:1px solid rgba(0,0,0,.1);border-radius:999px;font-size:10px;font-weight:800}.medicine-table{overflow:auto;margin-top:14px;border:1px solid var(--line);border-radius:16px}table{border-collapse:collapse;width:100%;min-width:1280px}th,td{padding:14px;border-bottom:1px solid var(--line);vertical-align:top;text-align:left}th{background:#fff3ee;font-size:11px;text-transform:uppercase;letter-spacing:.06em}td:first-child{font-weight:800}.ilmb{background:#fff9f6}.harm{background:#fff6f3}.docs{display:grid;grid-template-columns:repeat(2,1fr);gap:10px;margin-top:14px}.doc{padding:14px;border:1px solid var(--line);border-radius:12px}.doc small{display:block;color:var(--muted)}.identity{display:flex;gap:8px;flex-wrap:wrap;margin-top:12px}.identity span{padding:8px 10px;border-radius:999px;background:#fff3ee;border:1px solid var(--line);font-size:12px}.boundary{margin-top:18px;padding:14px;border-left:4px solid var(--rose);background:var(--soft);border-radius:10px}.empty{color:var(--muted);padding:16px 0}.actions{display:flex;gap:10px;flex-wrap:wrap;margin-top:16px}.actions a{padding:10px 14px;border-radius:999px;text-decoration:none;border:1px solid var(--line);color:var(--ink);background:#fff}.actions a.primary{background:var(--rose);color:#fff;border-color:var(--rose)}@media(max-width:900px){.summary,.cards,.docs{grid-template-columns:1fr}.hero{padding:20px}.top{align-items:flex-start;flex-direction:column-reverse}}
</style></head><body><main class="wrap"><div class="top"><a class="back" href="/app/">← My Happy Space</a><div class="brand"><b>I Love My Body</b><small>MY HOSPITAL REVIEW</small></div></div><section class="hero"><div class="ey">REPORTS · PRESCRIPTIONS · TWO PATHS</div><h1>Understand what your records are saying.</h1><p>We start with what is reassuring, then show what needs attention, then what remains unknown. Medicines are explained as desired effect → mechanism → collateral burden → ILMB same-goal target → measurement. LOINC, ChEBI and pathway identities stay in the background.</p><div class="actions"><a class="primary" href="/app/test-results.php">Add exact test values</a><a href="/app/#records">Upload reports / prescriptions</a></div></section><div id="loading">Building your review…</div><div id="content" hidden><div class="summary"><div class="sum"><div class="ey">REASSURING</div><b id="goodN">0</b><span>Within the printed reference range</span></div><div class="sum"><div class="ey">NEEDS ATTENTION</div><b id="attnN">0</b><span>Outside the printed range</span></div><div class="sum"><div class="ey">UNKNOWN / NOT YET MAPPED</div><b id="unkN">0</b><span>Kept open rather than guessed</span></div></div><section class="section"><div class="ey">MY REPORTS</div><h2>Optimistic, factual reading</h2><p class="lead" id="summaryText"></p><div class="cards" id="results"></div></section><section class="section"><div class="ey">MY PRESCRIPTION</div><h2>Why each medicine is there — and what ILMB is trying to achieve</h2><p class="lead">A side effect listed here is a known possibility, not something we assume you personally have. ILMB does not claim direct receptor equivalence unless it is demonstrated.</p><div class="medicine-table"><table><thead><tr><th>Medicine</th><th>Desired effect</th><th>How it achieves it</th><th>Important collateral / side-effect path</th><th>ILMB target</th><th>What proves the result</th></tr></thead><tbody id="meds"></tbody></table></div></section><section class="section"><div class="ey">SOURCE DOCUMENTS</div><h2>What has been received</h2><div class="docs" id="docs"></div></section><section class="section"><div class="ey">BACKGROUND IDENTITY LAYER</div><h2>How the database keeps the meaning exact</h2><div class="identity" id="identity"></div><div class="boundary" id="boundary"></div></section></div></main><script>
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
async function load(){try{const r=await fetch('hospital-review-api.php');const j=await r.json();if(!r.ok||!j.ok)throw Error(j.error||'Could not build the review.');document.querySelector('#loading').hidden=true;document.querySelector('#content').hidden=false;goodN.textContent=j.summary.reassuring;attnN.textContent=j.summary.attention;unkN.textContent=j.summary.unknown;summaryText.textContent=j.summary.message;results.innerHTML=j.results.length?j.results.map(x=>`<article class="result ${x.status==='reassuring'?'good':x.status==='attention'?'attn':'unknown'}"><span class="pill">${esc(x.status.toUpperCase())}</span><h3>${esc(x.name)}</h3><b>${esc(x.value)} ${esc(x.unit||'')}</b><p>${esc(x.headline)}</p><p>${esc(x.meaning)}</p><small>${x.range?'Printed range: '+esc(x.range):'No machine-readable range'}${x.loinc?' · LOINC '+esc(x.loinc):''}</small></article>`).join(''):'<p class="empty">No structured test values yet. Add values exactly as printed on the report.</p>';meds.innerHTML=j.medicines.length?j.medicines.map(m=>`<tr><td>${esc(m.reported_name)}<br><small>${esc(m.strength_text||'')}</small></td><td>${esc(m.effect)}</td><td>${esc(m.mechanism)}</td><td class="harm">${esc(m.collateral)}</td><td class="ilmb">${esc(m.ilmb)}</td><td>${esc(m.measure)}</td></tr>`).join(''):'<tr><td colspan="6">No active medicines recorded.</td></tr>';docs.innerHTML=j.documents.length?j.documents.map(d=>`<div class="doc"><b>${esc(d.original_filename||d.document_type)}</b><small>${esc(d.document_date||'Date not supplied')} · ${esc(String(d.document_type).replaceAll('_',' '))}</small><p>${esc(d.patient_message)}</p></div>`).join(''):'<p class="empty">No documents uploaded yet.</p>';identity.innerHTML=Object.entries(j.identity_layer).map(([k,v])=>`<span><b>${esc(k.toUpperCase())}</b> · ${esc(v)}</span>`).join('');boundary.textContent=j.boundary}catch(e){loading.textContent=e.message}}load();
</script></body></html>